+    private sealed class FaissMetadataFile
+    {
+        [JsonPropertyName("nextId")]
+        public long NextId { get; set; }
+
+        [JsonPropertyName("entries")]
+        public Dictionary<long, FaissEntry>? Entries { get; set; }
+    }
